import Component from 'flarum/common/Component';
import { t } from '../util';

/** "4 of 15 chapters read" over a bar. */
export default class ProgressBar extends Component {
  view() {
    const {
      done,
      total
    } = this.attrs;
    const percent = total ? Math.round(done / total * 100) : 0;
    return m("div", {
      className: "AnthologyProgress"
    }, m("div", {
      className: "AnthologyProgress-bar",
      role: "progressbar",
      "aria-valuemin": "0",
      "aria-valuemax": total,
      "aria-valuenow": done
    }, m("span", {
      style: {
        width: percent + '%'
      }
    })), m("div", {
      className: "AnthologyProgress-text"
    }, t('series.progress', {
      done,
      total
    })));
  }
}
flarum.reg.add('ernestdefoe-anthology', 'forum/components/ProgressBar', ProgressBar);